import type { CSSProperties } from "react";
import Link from "next/link";
import { comparisons, featuredMetrics } from "@/lib/data";
import ChooseBoxes from "./ChooseBoxes";

export default function FeaturedComparison({
  slug = "iphone-16-pro-vs-galaxy-s25-ultra",
}: {
  slug?: string;
}) {
  const c = comparisons.find((x) => x.slug === slug) ?? comparisons[0];
  const [a, b] = c.products;

  return (
    <section className="section featured">
      <div className="featured-label">✦ FEATURED COMPARISON</div>
      <div className="featured-head">
        <h2>
          {a.name} <span>vs</span> {b.name}
        </h2>
        <p>{c.tagline}</p>
      </div>

      <div className="featured-grid">
        <div className="featured-products">
          <div className="featured-product">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={a.img}
              alt={a.name}
              style={{ width: "100%", height: 180, objectFit: "contain" }}
            />
            <h3>{a.name}</h3>
            <small>{a.brand}</small>
            <strong>▣ {a.score}/100</strong>
            <label>ChoiceLens Score</label>
          </div>
          <div className="big-vs">VS</div>
          <div className="featured-product">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={b.img}
              alt={b.name}
              style={{ width: "100%", height: 180, objectFit: "contain" }}
            />
            <h3>{b.name}</h3>
            <small>{b.brand}</small>
            <strong>▣ {b.score}/100</strong>
            <label>ChoiceLens Score</label>
          </div>
        </div>

        <div className="metrics">
          {featuredMetrics.map((m) => (
            <div className="metric" key={m.label}>
              <div>
                {m.icon} <b>{m.label}</b>
              </div>
              <div className="metric-line">
                <span>{a.name}</span>
                <i style={{ "--score": `${m.a}%` } as CSSProperties}></i>
                <b>{m.a}</b>
              </div>
              <div className="metric-line">
                <span>{b.name}</span>
                <i style={{ "--score": `${m.b}%` } as CSSProperties}></i>
                <b>{m.b}</b>
              </div>
            </div>
          ))}
        </div>

        <div>
          <ChooseBoxes
            nameA={a.name}
            nameB={b.name}
            notesA={c.chooseNotes[0]}
            notesB={c.chooseNotes[1]}
          />
          <Link href={`/compare/${c.slug}`} className="view-all">
            Lihat detail comparison →
          </Link>
        </div>
      </div>
    </section>
  );
}
